'use strict';
const $=id=>document.getElementById(id),E=window.ArcadeEconomy,P=window.ArcadePractice;
const worlds={horse:{title:'Horse Race',tag:'TIGER DOWNS',note:'Race the pace horse. Chase a new best.',src:'races/horse.html?v=review-56',category:'horse',art:'races/horse-art/championship-course-v37.webp',sprite:'races/horse-art/gallop-hd-v37.webp',character:true,columns:4,rows:2,frame:1},jetski:{title:'Wave Riders Ignition',tag:'RIDE THE HYDRO BOOST',note:'Race the coast. Charge your surge.',src:'wave/index.html?v=review-56',category:'jetski',art:'wave/bay.png',sprite:'wave/cars.png',character:true,columns:2,rows:2,frame:0},subway:{title:'Skyrail Subway Run',tag:'3D HARBOR LINE',note:'Follow the coins. Jump oncoming trains.',src:'races/subway.html?v=review-56',category:'subway',art:'subway/metro-hero.png?v=subway-run-18'},sprint:{title:'Dirt Track Championship',tag:'CHASE DUST. TAKE THE LEAD.',note:'Drift the clay. Charge your nitro.',src:'dirt/index.html?v=review-56',category:'car',art:'dirt/art/cover-v41.webp'},castle:{title:'Castle in the Clouds',tag:'BUILD A FLOATING KINGDOM',note:'Raise towers and connect skybridges.',src:'castle/index.html?v=review-56',art:'castle/island-castle-hd-final.jpg',video:true},seed:{title:'Seed of Genius',tag:'GROW SOMETHING GREAT',note:'Little facts. Extraordinary growth.',src:'seed/index.html?v=review-56',art:'seed-thumb.jpg',video:true},hangar:{title:'Neon Auto Shop',tag:'BUILD YOUR DREAM RACER',note:'Power up your spectacular machine.',src:'hangar/index.html?v=review-56',art:'hangar-thumb.jpg',video:true},pong:{title:'Ping-Pong Rally',tag:'CHARGE YOUR FIREBALL',note:'Beat the clock. Ignite your next return.',src:'pong/index.html?v=review-56',art:'pong/art/cover-v39.webp'},invaders:{title:'Star Defenders',tag:'DEFEND YOUR GALAXY',note:'Fast facts. Explosive laser combos.',src:'invaders/index.html?v=review-56',art:'invaders/nebula-v1.png'},dragon:{category:'dragon',title:'Dragon Sky Quest',tag:'THE FJORD FLIGHT',note:'Fly the valley. Three seconds to land your fire.',src:'dragon/index.html?v=review-56',art:'dragon/art/cover-v45.webp'}};
let selected=null,mode='play',pending='play',storeCategory='all',tab='races',toastTimer,frameUnloadTimer=null,frameNavigation=0;
function send(data){if(selected&&$('game').contentWindow)$('game').contentWindow.postMessage(data,location.origin)}
function gear(){return E.gear(worlds[selected]?.category)}
function sync(){syncPractice();const s=E.getState();document.querySelectorAll('[data-coins]').forEach(n=>n.textContent=s.coins.toLocaleString());$('trophyNote').textContent=s.trophies.length?s.trophies.length+' of 10 adventure trophies':'Your first trophy is waiting';const next=E.catalog.filter(i=>i.category==='car'&&i.unlockAt>s.lifetimeEarned)[0];$('nextTitle').textContent=next?'Next up: '+next.name:'Your dream garage is unlocked!';$('nextNote').textContent=next?(next.unlockAt-s.lifetimeEarned).toLocaleString()+' more coins to unlock. Save or spend, you choose.':'Pick your favorite gear and keep collecting trophies.';$('upgradeMeter').style.width=next?Math.min(100,s.lifetimeEarned/next.unlockAt*100)+'%':'100%';$('storeNote').textContent=s.pendingUnlocks.length?'✨ New gear unlocked!':s.coins.toLocaleString()+' coins to spend';send({type:'arcade-wallet',coins:s.coins});send({type:'arcade-gear',gear:gear()});}
function renderTiles(){const keys=['horse','jetski','subway','sprint','castle','seed','hangar','pong','invaders','dragon'];$('tiles').style.gridTemplateColumns='';$('tiles').innerHTML=keys.map(key=>{const w=worlds[key];return `<article class="tile" data-tile="${key}"><div class="art" style="background:${w.bg||'#bbe5e2'}">${w.art?`<img src="${w.art}" alt="${w.title}">`:`<canvas width="720" height="420" data-sprite="${key}" role="img" aria-label="${w.title}"></canvas>`}${w.character?`<canvas width="720" height="420" data-sprite="${key}" role="img" aria-label="Your racer"></canvas>`:''}<span class="badge">${w.tag}</span></div><div class="copy"><h3>${w.title}</h3><p>${w.note}</p><button class="playButton" data-open="${key}" data-action="play">Let’s play →</button><div class="tileTools">${w.video?`<button data-open="${key}" data-action="video">▶ Watch video</button>`:''}<button data-open="${key}" data-action="demo">Watch demo</button></div></div></article>`}).join('');$('tiles').querySelectorAll('[data-sprite]').forEach(c=>{const w=worlds[c.dataset.sprite],img=new Image();img.onload=()=>{const cw=img.width/w.columns,ch=img.height/w.rows,ctx=c.getContext('2d'),scale=Math.min(650/cw,330/ch);ctx.drawImage(img,w.frame%w.columns*cw,Math.floor(w.frame/w.columns)*ch,cw,ch,(720-cw*scale)/2,(420-ch*scale)/2,cw*scale,ch*scale)};img.src=w.sprite});$('tiles').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openWorld(b.dataset.open,b.dataset.action));}
function openWorld(key,action='play'){if(!worlds[key])return;clearTimeout(frameUnloadTimer);frameUnloadTimer=null;frameNavigation++;const tile=document.querySelector(`[data-tile="${key}"]`),rect=tile?.getBoundingClientRect();selected=key;mode=action;pending=action;$('roomTitle').textContent=worlds[key].title;$('watchRoom').hidden=!worlds[key].video;$('room').hidden=false;$('homeScreen').inert=true;$('loading').hidden=false;document.body.style.overflow='hidden';if(rect&&$('room').animate&&!matchMedia('(prefers-reduced-motion: reduce)').matches)$('room').animate([{clipPath:`inset(${rect.top}px ${innerWidth-rect.right}px ${innerHeight-rect.bottom}px ${rect.left}px round 24px)`,opacity:.7},{clipPath:'inset(0px 0px 0px 0px round 0px)',opacity:1}],{duration:500,easing:'cubic-bezier(.2,.8,.2,1)'});$('game').src=worlds[key].src+(worlds[key].src.includes('?')?'&':'?')+'practice=store-21';history.replaceState(null,'','#'+key);sync();}
function home(){const unloadNavigation=++frameNavigation;selected=null;$('room').hidden=true;$('homeScreen').inert=false;document.body.style.overflow='';history.replaceState(null,'',location.pathname);clearTimeout(frameUnloadTimer);frameUnloadTimer=setTimeout(()=>{if(frameNavigation===unloadNavigation&&!selected)$('game').src='about:blank'},0);sync()}
function command(action){mode=action;pending=action;send({type:'arcade-command',action,gear:gear()});sync()}
$('game').onload=()=>{if(!selected)return;if(selected==='subway'){sync();return}$('loading').hidden=true;send({type:'arcade-command',action:pending,gear:gear()});sync()};
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function coinBurst(amount){notify('+'+amount+' coins!');for(let i=0;i<9;i++){const p=document.createElement('span');p.className='coinFly';p.textContent='●';p.style.left=(innerWidth*.68+Math.random()*90)+'px';p.style.top=(80+Math.random()*70)+'px';p.style.animationDelay=i*.035+'s';document.body.append(p);setTimeout(()=>p.remove(),1100)}}
function showStore(automatic=false){if(selected&&!automatic)send({type:'arcade-pause'});if($('sidebarDialog').open)$('sidebarDialog').close();const s=E.getState();if(automatic&&s.pendingUnlocks.length){const relevant=s.pendingUnlocks.find(id=>E.catalog.find(i=>i.id===id)?.category===worlds[selected]?.category)||s.pendingUnlocks[0];storeCategory=E.catalog.find(i=>i.id===relevant).storeCategory||E.catalog.find(i=>i.id===relevant).category;$('storeMessage').textContent='✨ Unlocked! Your hard work opened new gear. Buy your favorite or keep saving.'}else {storeCategory='all';$('storeMessage').textContent='Pick a collection, explore your favorites, and make your next upgrade.';}renderStore();if(!$('storeDialog').open)$('storeDialog').showModal()}
function renderStore(){ArcadeShop.render(storeCategory,c=>{storeCategory=c;renderStore()},()=>{sync();renderStore()},notify)}
function showTrophies(){if($('sidebarDialog').open)$('sidebarDialog').close();const s=E.getState();$('trophies').innerHTML=Object.entries(worlds).map(([id,w])=>`<article class="trophy ${s.trophies.includes(id)?'':'locked'}"><span>${s.trophies.includes(id)?'🏆':'🔒'}</span><h3>${w.title}</h3><small>${s.trophies.includes(id)?'Adventure mastered!':'Finish to collect'}</small></article>`).join('');$('trophyDialog').showModal()}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==$('game').contentWindow||!selected)return;const d=event.data||{};if(d.type==='arcade-practice-progress'){syncPractice();return}if(d.type==='arcade-practice-home'){home();return}if(d.type==='arcade-ready'){if(selected==='subway')$('loading').hidden=true;if(selected==='horse'||selected==='subway')send({type:'arcade-command',action:pending,gear:gear()});sync();return}if(d.type==='arcade-mode'&&['play','demo','video'].includes(d.mode)){mode=pending=d.mode;return}if(d.type==='arcade-reward'&&mode==='play'&&(!d.game||d.game===selected)){if(!Number.isInteger(d.amount)||d.amount<1||d.amount>100||typeof d.id!=='string'||!d.id.length||d.id.length>180)return;const r=E.reward(d.amount,selected+':'+d.id);if(r.ok){sync();coinBurst(r.amount)}}if(d.type==='arcade-complete'&&mode==='play'&&(!d.game||d.game===selected)){const r=d.won===false?{earned:false}:E.complete(selected);sync();if(r.earned)notify('🏆 '+worlds[selected].title+' trophy earned!');if(E.getState().pendingUnlocks.length)showStore(true)}});
$('sidebarButton').onclick=()=>$('sidebarDialog').showModal();$('back').onclick=home;$('watchRoom').onclick=()=>command('video');$('demoRoom').onclick=()=>command('demo');$('playRoom').onclick=()=>command('play');$('roomStore').onclick=()=>showStore();['walletButton','openStoreHero','storeButton'].forEach(id=>$(id).onclick=()=>showStore());$('trophyButton').onclick=showTrophies;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)return;if(d.id==='checkDialog')$('closeCheck').click();else d.close()}));$('storeDialog').addEventListener('close',()=>{E.acknowledgeUnlocks();sync();if(selected)$('game').focus()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('on',n===b));renderTiles()});window.addEventListener('resize',()=>updateScroll());window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()});window.addEventListener('storage',()=>{sync();if($('storeDialog').open)renderStore()});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('storeDialog').open&&!$('trophyDialog').open&&!$('sidebarDialog').open&&!$('room').hidden)home()});sync();renderTiles();

function updateScroll(){const t=$('tiles'),max=t.scrollHeight-t.clientHeight;$('scrollRail').hidden=max<2;$('cardScroll').value=max>0?Math.round(t.scrollTop/max*100):0}
$('tiles').addEventListener('scroll',updateScroll,{passive:true});$('cardScroll').addEventListener('input',()=>{const t=$('tiles');t.scrollTop=(t.scrollHeight-t.clientHeight)*Number($('cardScroll').value)/100});new ResizeObserver(updateScroll).observe($('tiles'));document.querySelectorAll('.art img').forEach(i=>i.addEventListener('load',updateScroll));requestAnimationFrame(updateScroll);

function syncPractice(){window.PathwayUI?.render();}

// Keep keyboard and screen-reader order aligned with the game-first landing page.
document.querySelector('.adventures')?.after(document.querySelector('.pathwayPanel'));
